contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        require(address(this).balance >= _am);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: _am}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool ok;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (ok && balAfter == balBefore - _am) ||
            (!ok && balAfter == balBefore)
        );
    }

    receive() external payable {}
}

